-- ----------------------------------------------
-- CARD_ACCOUNT
-- ----------------------------------------------
DROP TABLE IF EXISTS card_account;
CREATE TABLE card_account (
    card_id TEXT,
    cif TEXT,
    card_type TEXT,
    card_number_masked TEXT,
    credit_limit NUMERIC(24,6),
    current_balance NUMERIC(24,6),
    status TEXT,
    issue_date DATE,
    branch_id TEXT,
    department_id TEXT,
    portfolio_id TEXT,
    source_system TEXT,
    PRIMARY KEY (card_id)
);
CREATE INDEX idx_card_account_cif ON card_account(cif);
COMMIT;
